def _commit_unless_in_transaction(self):
    """Commit the connection's work unless an explicit transaction is open.

    SQLAlchemy 2.0 no longer autocommits DML or DDL, so statements run
    outside of ``begin()`` / ``with db:`` must be committed explicitly.
    """
    if not self.in_transaction:
        self.executable.commit()

def _execute(self, statement, parameters=None):
    """Execute a write statement and commit it unless in a transaction."""
    conn = self.executable
    if parameters is None:
        result = conn.execute(statement)
    else:
        result = conn.execute(statement, parameters)
    if not result.returns_rows:
        self._commit_unless_in_transaction()
    return result

